mapper.update:
UPDATE contract_reinstatement
SET reinstatement_status = 'UNPAID_SETTLED',
    unpaid_settled_at = #{unpaidSettledAt}
WHERE reinstatement_id = #{reinstatementId}
  AND reinstatement_status = 'APPLIED'

UPDATE contract_reinstatement
SET reinstatement_status = 'COMPLETED',
    completed_at = #{completedAt}
WHERE reinstatement_id = #{reinstatementId}
  AND reinstatement_status = 'UNPAID_SETTLED'

UPDATE contract_reinstatement
SET reinstatement_status = 'CANCELLED',
    cancelled_at = #{cancelledAt}
WHERE reinstatement_id = #{reinstatementId}
  AND reinstatement_status IN ('APPLIED', 'UNPAID_SETTLED')

UPDATE contract
SET contract_status = #{nextStatus},
    has_unpaid_premium = FALSE
WHERE policy_number = #{policyNumber}
  AND contract_status = #{currentStatus}

UPDATE contract_reinstatement
SET underwriting_request_id = #{underwritingRequestId}
WHERE reinstatement_id = #{reinstatementId}
  AND reinstatement_status IN ('APPLIED', 'UNPAID_SETTLED')
